package io.xeros.content.questing;
import io.xeros.Server;import io.xeros.model.entity.player.*;import io.xeros.model.entity.npc.*;import io.xeros.model.collisionmap.WorldObject;import io.xeros.model.cycleevent.Event;import java.util.*;
public final class RestlessGhost extends ClassicQuest {
 private static final Map<NPC,RestlessGhost> OWNERS=new IdentityHashMap<>();
 private NPC ghost,skeleton;private boolean opened;
 public RestlessGhost(Player p){super(p);}public String getName(){return "The Restless Ghost";}public String getDisplayName(){return "O fantasma inquieto";}public int getCompletionStage(){return 5;}
 public List<String> getCompletedRewardsList(){return Arrays.asList("1 ponto de missao","1.125 Prayer XP","Ghostspeak amulet");}
 public List<String> getJournalText(int s){switch(s){case 0:return Arrays.asList("Fale com Father Aereck na igreja de Lumbridge.");case 1:return Arrays.asList("Aereck pediu ajuda para libertar o fantasma do cemiterio.","Procure Father Urhney na cabana no sudoeste do pantano.");case 2:return Arrays.asList("Urhney me deu um Ghostspeak amulet.","Equipe o amuleto e abra o Coffin no cemiterio de Lumbridge.","Converse com o Restless ghost.");case 3:return Arrays.asList("O fantasma perdeu o cranio, roubado por um mago.","Procure o Skull no altar do subsolo da Wizards' Tower.","Um esqueleto protege o altar; lutar com ele e opcional.");case 4:return Arrays.asList("Devolva o Skull ao Coffin aberto do cemiterio de Lumbridge.","Equipe o Ghostspeak amulet para falar com o fantasma.");default:return Arrays.asList("Devolvi o cranio ao tumulo e o fantasma encontrou a paz.");}}
 public void giveQuestCompletionRewards(){exactReward(5,1125);}
 public static boolean visible(Player p,NPC n){RestlessGhost q=OWNERS.get(n);return q==null||q.player==p;}
 private NPC spawn(int id,int x,int y){NPC n=new NPC(id,new Position(x,y,0));n.randomWalk=false;n.walkingType=0;n.getBehaviour().setWalkHome(false);n.getBehaviour().setRespawn(false);n.getBehaviour().setAggressive(false);OWNERS.put(n,this);return n;}
 private void remove(NPC n){if(n!=null){OWNERS.remove(n);if(n.getIndex()>0&&NPCHandler.npcs[n.getIndex()]==n)n.unregisterInstant();}}
 public void process(){if(ghost!=null&&(ghost.isUnregister()||isQuestCompleted()||player.heightLevel!=0||Math.abs(player.absX-3250)>35||Math.abs(player.absY-3192)>35)){remove(ghost);ghost=null;opened=false;}if(skeleton!=null&&(skeleton.isUnregister()||skeleton.isDeadOrDying()||player.heightLevel!=0||Math.abs(player.absY-9566)>50)){remove(skeleton);skeleton=null;}if(getStage()>=2&&getStage()<=4&&opened&&ghost==null&&near(3249,3192,0))ghost=spawn(922,3250,3193);}
 public void logout(){remove(ghost);remove(skeleton);ghost=null;skeleton=null;opened=false;}
 public boolean handleNpcClick(NPC n,int option){int id=n.getNpcId();boolean a=id==921&&local(n,3243,3208,0),u=id==923&&local(n,3145,3175,0),g=id==922&&OWNERS.get(n)==this;if(!a&&!u&&!g)return false;if(option!=1||!ready()||!nearbyNpc(n))return true;int s=getStage();
 if(a){if(s==0)offer(n,0,"Um fantasma assombra o cemiterio. Meu amigo Father Urhney entende desses assuntos.","Vou procurar Father Urhney.",()->{step(0,1);say(id,"Ele mora sozinho no sudoeste do pantano de Lumbridge.");});else say(id,isQuestCompleted()?"Obrigado por ajudar aquela alma a descansar.":"Father Urhney pode ajuda-lo a entender o fantasma.");}
 else if(u){if(s==0)say(id,"Estou tentando viver em paz. Fale com Father Aereck na igreja.");else if(s==1)offer(n,s,"Nao quero voltar a igreja, mas posso emprestar meu Ghostspeak amulet. Use-o para ouvir os mortos.","Receber o amuleto.",()->{if(exchange(new int[0][],new int[][]{{552,1}})){step(1,2);say(id,"Equipe o Ghostspeak amulet antes de conversar com o fantasma.");}});else if(!owns(552))offer(n,s,"Perdeu o amuleto? Ainda posso ajuda-lo.","Pedir outro Ghostspeak amulet.",()->replace(552));else say(id,"O amuleto precisa estar equipado para voce entender os mortos.");}
 else if(player.playerEquipment[Player.playerAmulet]!=552)say(id,"Wooooo! Woooooo!");
 else if(s==2)offer(n,s,"Finalmente alguem me entende! Um mago roubou meu cranio. Sem ele nao consigo descansar.","Vou procurar seu cranio.",()->{step(2,3);say(id,"Procure onde os magos vivem, na torre a sudoeste daqui.","Devolva o Skull ao meu Coffin.");});else say(id,"Por favor, devolva meu Skull ao Coffin para que eu possa descansar.");return true;}
 public boolean handleObjectClick(WorldObject o,int option){if(o.x==3249&&o.y==3192&&o.id==2145){if(!near(o.x,o.y,o.height))return true;if(option==2){opened=false;remove(ghost);ghost=null;player.sendMessage("Voce fecha o Coffin.");return true;}if(option!=1)return true;opened=true;if(isQuestCompleted())player.sendMessage("O Coffin esta em paz. O fantasma partiu.");else if(getStage()<2)player.sendMessage("Voce abre o Coffin. Uma presenca assombra o cemiterio.");else{process();player.sendMessage("Voce abre o Coffin. Fale com o Restless ghost.");}return true;}
 if(o.x==3120&&o.y==9566&&(o.id==2146||o.id==15050||o.id==15051)){if(option!=1||!near(o.x,o.y,o.height))return true;if(getStage()!=3&&getStage()!=4){player.sendMessage("Nao ha nada que voce precise levar deste altar.");return true;}if(owns(553)){player.sendMessage("Voce ja encontrou o Skull. Confira sua mochila ou banco.");return true;}if(exchange(new int[0][],new int[][]{{553,1}})){if(getStage()==3)step(3,4);else checkpoint();player.sendMessage("Voce encontra o Skull. Um Skeleton desperta: voce pode fugir sem enfrenta-lo.");if(skeleton==null||skeleton.isUnregister()||skeleton.isDeadOrDying()){skeleton=spawn(70,3118,9566);skeleton.attackEntity(player);}}return true;}return false;}
 public boolean handleItemOnObject(int item,int obj,int x,int y){if(item!=553||obj!=2145||x!=3249||y!=3192)return false;if(!near(x,y,0)||getStage()!=4)return true;if(!opened){player.sendMessage("Abra o Coffin antes de devolver o Skull.");return true;}if(!exchange(new int[][]{{553,1}},new int[0][]))return true;NPC departing=ghost;ghost=null;if(departing!=null){departing.forceChat("Obrigado! Finalmente posso descansar.");Server.getEventHandler().submit(new Event<NPC>("restless_departure",departing,1){int ticks;public void execute(){if(++ticks<=6&&!attachment.isUnregister())attachment.moveTowards(3256,3191,false);else{remove(attachment);stop();}}});}finish(4,5,1125);player.sendMessage("O cranio esta no lugar. O fantasma segue para o rio e desaparece.");return true;}
}
